# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""log_softmax_backward (aten::_log_softmax_backward_data semantics) in Triton.

dx = grad_output - exp(output) * sum(grad_output, dim), accumulated in fp32.

Value-returning, no DPS. The result dtype follows the `input_dtype` argument
(same as the FlagGems reference); the store casts from fp32.

Dispatch is metadata-only (no physical-core constants) and deterministic (no
autotune: on this target the selector was measured returning an ~14.3us config
after timing an ~8.1us one for the same key, and its picks varied ~5% run to
run in the buckets where it did help):
  * contiguous layout, reduction dim effectively last (I == 1)
      - K <= 1024: single-pass row kernel, whole row tile in UB (3E traffic),
        BLOCK_M = max(1, min(16, 4096 / next_pow2(K)))
      - 1024 < K <= 4096: single-pass row kernel with a fixed 2-row tile
      - K > 4096: two-pass streaming kernel, fixed 2-row x 4096-element tile
  * other collapsible layouts -> one reduction lane per program, explicit strides

Both last-dim kernels take an EVEN constexpr that drops all masks and the
`other` operand when the tile covers the data exactly.
"""

import torch
import triton
import triton.language as tl

_CACHE_MAX_K = 4096  # whole-K row tile resident in UB up to this K
_LANE_BLOCK_K = 1024  # verified UB-feasible 1D tile for the strided path


@triton.jit
def _lsb_last_cached(
    g_ptr,
    y_ptr,
    dx_ptr,
    M,
    K,
    BLOCK_M: tl.constexpr,
    BLOCK_K: tl.constexpr,
    EVEN: tl.constexpr,
):
    pid = tl.program_id(0)
    rows = pid * BLOCK_M + tl.arange(0, BLOCK_M)
    k = tl.arange(0, BLOCK_K)
    off = rows[:, None] * K + k[None, :]
    if EVEN:
        # full tile in range and contiguous: no predicates, no masked access
        g = tl.load(g_ptr + off).to(tl.float32)
        y = tl.load(y_ptr + off).to(tl.float32)
        s = tl.sum(g, 1)
        dx = g - tl.exp(y) * s[:, None]
        tl.store(dx_ptr + off, dx.to(dx_ptr.dtype.element_ty))
    else:
        rmask = rows < M
        mask = rmask[:, None] & (k[None, :] < K)
        g = tl.load(g_ptr + off, mask=mask, other=0.0).to(tl.float32)
        y = tl.load(y_ptr + off, mask=mask, other=0.0).to(tl.float32)
        s = tl.sum(g, 1)
        dx = g - tl.exp(y) * s[:, None]
        tl.store(dx_ptr + off, dx.to(dx_ptr.dtype.element_ty), mask=mask)


@triton.jit
def _lsb_last_loop(
    g_ptr, y_ptr, dx_ptr, M, K, BLOCK_M: tl.constexpr, BLOCK_K: tl.constexpr
):
    pid = tl.program_id(0)
    rows = pid * BLOCK_M + tl.arange(0, BLOCK_M)
    rmask = rows < M
    koff = tl.arange(0, BLOCK_K)
    base = rows[:, None] * K
    s = tl.zeros([BLOCK_M], tl.float32)
    for k0 in range(0, K, BLOCK_K):
        k = k0 + koff
        mask = rmask[:, None] & (k[None, :] < K)
        g = tl.load(g_ptr + base + k[None, :], mask=mask, other=0.0).to(tl.float32)
        s += tl.sum(g, 1)
    for k0 in range(0, K, BLOCK_K):
        k = k0 + koff
        mask = rmask[:, None] & (k[None, :] < K)
        off = base + k[None, :]
        g = tl.load(g_ptr + off, mask=mask, other=0.0).to(tl.float32)
        y = tl.load(y_ptr + off, mask=mask, other=0.0).to(tl.float32)
        dx = g - tl.exp(y) * s[:, None]
        tl.store(dx_ptr + off, dx.to(dx_ptr.dtype.element_ty), mask=mask)


@triton.jit
def _lsb_lane(
    g_ptr,
    y_ptr,
    dx_ptr,
    K,
    I,
    so_g,
    sk_g,
    si_g,
    so_y,
    sk_y,
    si_y,
    so_d,
    sk_d,
    si_d,
    BLOCK_K: tl.constexpr,
):
    """One reduction lane (o, i) per program, explicit strides."""
    lane = tl.program_id(0)
    o = lane // I
    i = lane % I
    gb = o * so_g + i * si_g
    yb = o * so_y + i * si_y
    db = o * so_d + i * si_d
    koff = tl.arange(0, BLOCK_K)
    s = tl.zeros([1], tl.float32)
    for k0 in range(0, K, BLOCK_K):
        k = k0 + koff
        mask = k < K
        g = tl.load(g_ptr + gb + k * sk_g, mask=mask, other=0.0).to(tl.float32)
        s += tl.sum(g, 0)
    for k0 in range(0, K, BLOCK_K):
        k = k0 + koff
        mask = k < K
        g = tl.load(g_ptr + gb + k * sk_g, mask=mask, other=0.0).to(tl.float32)
        y = tl.load(y_ptr + yb + k * sk_y, mask=mask, other=0.0).to(tl.float32)
        dx = g - tl.exp(y) * tl.sum(s, 0)
        tl.store(dx_ptr + db + k * sk_d, dx.to(dx_ptr.dtype.element_ty), mask=mask)


def _group_stride(shape, strides, start, stop):
    """Collapse axes [start, stop) into (size, stride) if internally contiguous."""
    size = 1
    for a in range(start, stop):
        size *= shape[a]
    if size == 1:
        return size, 0
    stride = strides[stop - 1]
    for a in range(start, stop - 1):
        if shape[a] != 1 and strides[a] != strides[a + 1] * shape[a + 1]:
            return size, None
    return size, stride


def log_softmax_backward_data(grad_output, output, dim, input_dtype):
    shape = output.shape
    ndim = output.dim()
    d = dim + ndim if dim < 0 else dim

    K = shape[d]
    outer = 1
    for a in range(d):
        outer *= shape[a]
    inner = 1
    for a in range(d + 1, ndim):
        inner *= shape[a]

    out_dtype = (
        input_dtype if isinstance(input_dtype, torch.dtype) else grad_output.dtype
    )
    out = torch.empty(shape, dtype=out_dtype, device=grad_output.device)
    if outer * K * inner == 0:
        return out

    if inner == 1 and grad_output.is_contiguous() and output.is_contiguous():
        M = outer
        if K <= 1024:
            bk = triton.next_power_of_2(K)
            bm = max(1, min(16, 4096 // bk))
            even = (K == bk) and (M % bm == 0)
            _lsb_last_cached[(triton.cdiv(M, bm),)](
                grad_output, output, out, M, K, BLOCK_M=bm, BLOCK_K=bk, EVEN=even
            )
        elif K <= _CACHE_MAX_K:
            bk = triton.next_power_of_2(K)
            # fixed 2-row tile: autotune's picks over {1,2,4} rows varied by
            # ~5% run-to-run and never beat the middle choice consistently
            bm = 2
            even = (K == bk) and (M % bm == 0)
            _lsb_last_cached[(triton.cdiv(M, bm),)](
                grad_output, output, out, M, K, BLOCK_M=bm, BLOCK_K=bk, EVEN=even
            )
        else:
            # fixed 8192-element streaming tile: one row per program keeps each
            # DMA a single contiguous chunk (32KB float32 / 16KB half) and the
            # row accumulator scalar
            bm, bk = 1, 8192
            _lsb_last_loop[(triton.cdiv(M, bm),)](
                grad_output, output, out, M, K, BLOCK_M=bm, BLOCK_K=bk
            )
        return out

    gs = grad_output.stride()
    ys = output.stride()
    ds = out.stride()
    O_g, sg_o = _group_stride(shape, gs, 0, d)
    I_g, sg_i = _group_stride(shape, gs, d + 1, ndim)
    O_y, sy_o = _group_stride(shape, ys, 0, d)
    I_y, sy_i = _group_stride(shape, ys, d + 1, ndim)
    O_d, sd_o = _group_stride(shape, ds, 0, d)
    I_d, sd_i = _group_stride(shape, ds, d + 1, ndim)
    if None in (sg_o, sg_i, sy_o, sy_i, sd_o, sd_i):
        raise RuntimeError(
            "log_softmax_backward: unsupported non-collapsible strides "
            f"for shape {tuple(shape)} dim {dim}"
        )

    L = O_g * I_g
    _lsb_lane[(L,)](
        grad_output,
        output,
        out,
        K,
        I_g,
        sg_o,
        gs[d],
        sg_i,
        sy_o,
        ys[d],
        sy_i,
        sd_o,
        ds[d],
        sd_i,
        BLOCK_K=_LANE_BLOCK_K,
    )
    return out
